    if (_totalBudgetSpent) {
      return (
        budgetSpent: true,
        cancelled: false,
        error: null,
        text: null,
        summarizerCalls: summarizerCalls,
      );
    }
    if (text == null || text.isEmpty) {
      if (_runCancelled) {
        return (
          budgetSpent: false,
          cancelled: true,
          error: null,
          text: null,
          summarizerCalls: summarizerCalls,
        );
      }
      return (
        budgetSpent: false,
        cancelled: false,
        error: const CompactionException(
          'checkpoint escalation summarizer returned no text',
