        text: null,
        summarizerCalls: summarizerCalls,
      );
    }
    final appended = await _appendEscalationCheckpoint(range, flattened, text);
    if (appended != null) {
      if (_runCancelled) {
        return (
          budgetSpent: false,
          cancelled: true,
          error: null,
          text: null,
          summarizerCalls: summarizerCalls,
        );
      }
      return (
        budgetSpent: false,
        cancelled: false,
        error: appended,
        text: null,
        summarizerCalls: summarizerCalls,
      );
    }
    return (
      budgetSpent: false,
      cancelled: false,
      error: null,
      text: text,
      summarizerCalls: summarizerCalls,
    );
