      );
    }
    // Backend agent mode (issue #155): close the compaction bracket once
    // per run with the net freed delta (clamped — a restamped estimator
    // can report a slightly larger after-count than the usage-anchored
    // before-count).
    final before = _runTokensBefore;
    if (before != null) {
      final freed = before - tokens;
      cli._hep?.compactionEnd(freed < 0 ? 0 : freed);
      _runTokensBefore = null;
    }
  }

  /// Returns a user-facing hint for a compaction failure, pointing at the
  /// `smol` role config when the summarization model hit a provider limit.
  /// Moved here from agent_cli.dart (2800-line gate) — used only by the
  /// hooks' failure reporting.
  String _compactionFailureHint(Object error) {
    final text = error.toString();
    if (text.contains('usage limit') ||
        text.contains('access_terminated_error') ||
        text.contains('rate limit') ||
        text.contains('429')) {
      return '$error\n\n'
          'Compaction uses the `smol` role model (see `roles.smol` in '
          '~/.fah/config.yaml). The current smol model/provider returned '
          'the error above. Switch it to a model/key with available quota, '
          'e.g. via `/settings` → Agent models, or edit ~/.fah/config.yaml.';
    }
    return text;
  }

  @override
  void onBothRolesFailed(Object lastError) {
    final hint = _compactionFailureHint(lastError);
    cli.io.writeln('compaction both roles failed: $hint');
    cli.io.writeln(
      'compaction both roles failed; the agent cannot make progress '
      'until you switch models (e.g. `/model`) or start a new session '
      '(`/new`).',
    );
  }
}

/// The busy-row phase push (issue #653): a plain passthrough. The busy
/// row names the CURRENT activity — `Compacting context…` while the fold
/// runs, then the post-fold handback (`''`) clears the marker the moment
/// the compaction finishes, and later tool/stream labels stay marker-free.
/// The «[auto-compacted · continuing]» badge used to be appended to every
/// label here, so after any fold the row led with the stale marker for
/// the rest of the run (owner screenshot: `[auto-compacted ×7 · c…` over
/// active tool work). The badge lives on the status row only
/// (`_statusLine`, until the turn settles — issue #438 AC3).
extension AgentCliBusyPhase on AgentCli {
  /// Pushes a phase label onto the TUI busy row.
  void _pushBusyPhase(String phase) {
    busyPhasesForTest.add(phase);
    _tuiController?.setBusyPhase(phase);
  }
}

/// Auto/manual compaction run methods (moved from agent_cli.dart under the
/// repo's 2800-line size gate). Same library, so private state is in scope.

/// Formats the in-chat compaction report block (issue #276): tokens
/// before → after, freed count/percent, WHICH ENGINE did the summarizing
/// (the `smol`/`main` role — review major 3: a report that doesn't name
/// the engine can't be judged), how many records were hidden vs
/// summarized, and — when the pass actually wrote summary text — the
/// summary in a fenced block so the user can eyeball — and copy — what
/// the transcript was condensed to. A pass with no summary text (all
/// evictions went to hide, or the model returned blank — issue #578)
/// omits the block: an empty ```-fence says nothing and reads as a bug.
/// Pure; [_AgentCliCompactionReportPrinter.print] renders it.
///
/// gh-1636: the internal checkpoint text is debug output, not
/// conversation. By default ([details] false) the report is ONE short
/// marker line — `auto-compacted · ENGINE: N → M tokens (F freed ·
/// P%)`; the `records:` line and the fenced summary only render with
/// `details: true` (the `tui.showCompactionDetails` opt-in, or the
/// manual `/compact` — the on-demand expansion). The summary itself is
/// never lost: it stays in the session file, reachable via
/// `compact_expand`.
List<String> formatCompactionReport(
  AutoCompactorPass pass, {
  required bool auto,
  bool details = false,
}) {
  final freedRaw = pass.tokensBefore - pass.tokensAfter;
  // A restamped estimator can report a slightly larger after-count (same
  // clamp as onDone's HEP end frame): "-30 freed" reads as a bug.
  final freed = freedRaw < 0 ? 0 : freedRaw;
  final pct = pass.tokensBefore == 0
      ? 0
      : (freed * 100 / pass.tokensBefore).round();
  // gh-2097: an upward basis jump renders EXPLICITLY — the pass appended
  // only shrinkers, so an after-count above the before-count is the
  // session projection holding more than the in-memory view did at
  // measurement time (a second writer), not a compaction regression.
  // «0 freed · 0%» used to read the first honest measurement as one.
  final outcome = pass.basisReadTokens != null
      ? 'basis re-read: +${formatTokens(pass.basisReadTokens)}'
      : '$freed freed · $pct%';
  final engine = pass.fallback == null ? '' : ' · ${pass.fallback}';
  final passSuffix = pass.pass == 1 ? '' : ' · pass ${pass.pass}';
  final header = '${auto ? 'auto-compacted' : 'compacted'}$engine$passSuffix';
  // gh-1636: the default report — one line, no checkpoint text.
  if (!details) {
    return [
      '$header: ${pass.tokensBefore} → ${pass.tokensAfter} tokens ($outcome)',
    ];
  }
  final summary = pass.summary?.trim();
  return [
    header,
    'tokens: ${pass.tokensBefore} → ${pass.tokensAfter} ($outcome)',
    // Issue #673 AC3: the local-trim valve frees tokens WITHOUT hiding
    // session records or folding a summary — a bare "0 hidden · 0
    // summarized" next to a big freed count cannot describe a real
    // compaction. Name the in-memory drop so the line is truthful for
    // BOTH engines.
    if (pass.droppedMessages > 0)
      'records: ${pass.droppedMessages} dropped (in-memory) · '
          '${pass.hiddenRecords} hidden · '
          '${pass.summarizedMessages} summarized'
    else
      'records: ${pass.hiddenRecords} hidden · '
          '${pass.summarizedMessages} summarized',
    if (summary != null && summary.isNotEmpty) ...[
      'summary:',
      '```',
      _balanceSummaryFences(summary),
      '```',
    ],
  ];
}

/// gh-1755: balances unclosed code fences in compaction summaries so the
/// outer closing fence does not toggle markdown rendering into verbatim
/// code (an LLM summary that ends mid-fence used to swallow every row
/// the report rendered after it).
String _balanceSummaryFences(String summary) {
  final fencePattern = RegExp(r'^\s*```');
  final fenceCount = summary.split('\n').where(fencePattern.hasMatch).length;
  if (fenceCount.isOdd) {
    return '$summary\n```';
  }
  return summary;
}

/// Renders [formatCompactionReport] through the styled transcript writer
/// so both line mode and the TUI see the same block.
extension _AgentCliCompactionReportPrinter on AgentCli {
  void _printCompactionReport(AutoCompactorPass pass, {required bool auto}) {
    final lines = formatCompactionReport(
      pass,
      auto: auto,
      // gh-1636: an auto-fold prints the one-line marker unless
      // `tui.showCompactionDetails` opts in; a manual /compact is the
      // user's explicit ask — the on-demand expansion always renders the
      // full block.
      details: !auto || config.showCompactionDetails,
    );
    final header = lines.first;
    final body = lines.sublist(1);
    io.writeln(_style.teal('● $header'));
    for (final line in body) {
      io.writeln(line == '```' ? _style.dim(line) : line);
    }
  }
}

extension AgentCliCompactionRun on AgentCli {
  /// Runs the auto-compaction when the live transcript crosses the
  /// threshold. Returns whether a compaction pass actually ran and
  /// succeeded — the over-window guard's auto-continuation keys off this
  /// to resume only when the window was really freed.
  Future<bool> _maybeAutoCompact({bool forceE1Pass = false}) async {
    final session = _session;
    if (session == null) return false;
    if (_agent.state.messages.isEmpty) return false;
    // An aborted turn gets no fresh compaction pass (issue #1085 round-2
    // review): the sticky abort flag used to belt-throw CancelledException
    // out of the post-run compaction and print a spurious `error:` line
    // after the abort was already reported. The over-window guard simply
    // re-fires on the next turn if the transcript is still too big.
    if (_runAbortRequested) return false;
    // The same request-size basis as the loop's over-window guard and the
    // status-line meter (transcript + system-prompt/tool-schema overhead
    // when unanchored) — the threshold must trip on what the next request
    // actually carries.
    final tokens = _liveRequestTokens();
    // gh-1680 AC4: the additive message-count trigger — a model with a
    // learned cap compacts when the live count reaches `cap − margin`,
    // BEFORE the request, even when the token trigger is untouched. The
    // gate also consumes the one-shot E1 pass a cap-unknown refusal
    // armed (PR #1695).
    final model = _agent.state.model;
    final e1PassPending =
        forceE1Pass &&
        _modelCaps.isPremptivePassPending(model.provider, model.id);
    final overCap = _messageCapGateReached();
    if (!shouldCompact(
          tokens,
          _effectiveContextWindow,
          _effectiveCompactionSettings,
        ) &&
        !overCap) {
      return false;
    }
    _pushBusyPhase('Compacting context…');
    _logDiagnostic('auto-compact start sid=$_logSid tokens=$tokens');
    try {
      // gh-1729 review: when the E1 one-shot pass is the trigger, the
      // funnel's own re-check cannot see it (a cap-UNKNOWN model has no
      // learned cap to trip `_overMessageCap`, and the transcript sits
      // under the token trigger) — without `force` the pass would be
      // consumed and the funnel would silently no-op. Forced only at the
      // pre-flight ([_beginUserPrompt], `forceE1Pass`): the pass's
      // contract is a compaction BEFORE the next user request; the
      // post-run fold keeps its shipped no-op-when-under-trigger
      // behavior.
      await _runAutoCompact('[auto-compacted]', force: e1PassPending);
    } finally {
      // Hand the busy row back to the run even when the compaction throws
      // or is cancelled (issue #1085): a stale 'Compacting context…'
      // over the streamed turn reads as a compaction hang.
      _pushBusyPhase('');
    }
    // [_runAutoCompact] reports '[auto-compacted]' only on success; treat
    // the transcript size as the source of truth for the caller.
    // Issue #1085 M2a: continuation success = the transcript FITS THE
    // WINDOW now, not "any reduction". A reduce-but-still-over pass used
    // to read as success, the guard re-fired on the retried turn, and the
    // one-shot resume budget was burned on a transcript that still could
    // not be sent.
    final after = _liveRequestTokens();
    // PR #1695: success needs BOTH dimensions — a pass that only shrinks
    // tokens while the message count still trips the cap gate is not a
    // success; the caller retries relief and the funnel reports
    // exhaustion instead of silently re-arming a pass every turn.
    return after <= _effectiveContextWindow && !overCap;
  }

  /// The gh-1680 message-count gate shared by the loop and boot-cap
  /// passes: the known-cap pre-emptive trigger, or the one-shot E1 pass a
  /// cap-unknown refusal armed (consumed here so it fires exactly once
  /// per refusal). CONSUMING — call only from a path that runs a
  /// compaction when it returns true ([_maybeAutoCompact]); the boot-cap
  /// decision uses the peeking [_messageCapGatePending] instead.
  bool _messageCapGateReached() {
    final model = _agent.state.model;
    return messageCapTriggerReached(
          _agent.state.messages.length,
          _modelCaps.learnedCapFor(model),
        ) ||
        _modelCaps.takePremptivePass(model.provider, model.id);
  }

  /// The non-consuming twin of [_messageCapGateReached]: same compound
  /// gate, but the armed E1 one-shot pass is only PEEKED
  /// ([ModelCaps.isPremptivePassPending]), never removed. gh-1729 review:
  /// the boot-cap DECISION must not spend the pass — the lazy defer
  /// branch returns without running a compaction, and a pass consumed
  /// there is silently dropped (the next request rides out uncapped and
  /// re-learns the refusal the hard way — exactly what the pass exists to
  /// avoid). The pass fires (and is consumed) where a compaction actually
  /// runs: the first turn's pre-flight, or the boot's synchronous
  /// over-window last resort.
  bool _messageCapGatePending() {
    final model = _agent.state.model;
    return messageCapTriggerReached(
          _agent.state.messages.length,
          _modelCaps.learnedCapFor(model),
        ) ||
        _modelCaps.isPremptivePassPending(model.provider, model.id);
  }

  /// The shared request-size estimate for compaction decisions (see
  /// [estimateRequestTokens]): identical basis to the status-line meter
  /// and the loop guard.
  int _liveRequestTokens() => estimateRequestTokens(
    _agent.state.messages,
    systemPrompt: _agent.state.systemPrompt,
    tools: _agent.state.tools,
  );

  /// gh-1425 AC3 (the resume boot cap, lazy rework): a resumed session
  /// whose projected context is over the compaction trigger must never
  /// make the OPEN itself wait on an LM summarization pass (the goal_builder
  /// and yoclip incidents: 3.5-minute boot caps read as hung opens and
  /// were killed — every reopen re-paid them). Two regimes:
  ///
  /// - over the WINDOW: no request can ever be sent — the mechanical
  ///   local-trim valve caps INSTANTLY (milliseconds, zero LM calls);
  ///   the durable LM compaction happens through the normal paths.
  /// - over the TRIGGER but inside the window: the next request is legal
  ///   as-is, so boot defers — the first turn's pre-flight
  ///   ([_maybeAutoCompact] runs before every prompt) owns the durable
  ///   compaction BEFORE any user work continues. The meter idles at the
  ///   honest pre-cap number (≤100%). Also runs on mid-REPL session
  ///   switches (same detonation class).
  ///
  /// Degradation (AC5) rides the shared [AutoCompactorFactory] pipeline: a
  /// summarizer failure falls to the existing local-trim valve with its
  /// visible `[context trimmed]` note, so the next request is still ≤
  /// window and the boot survives any failure — the catch below only
  /// backstops unexpected throws (a broken session must still boot), and
  /// it notes the crash VISIBLY (dim, transcript-diagnosable) instead of
  /// only in the diagnostic log: a silently crashed cap reads exactly like
  /// the pre-fix over-window idle state.
  /// Idempotent (kill/resume mid-pass): a failed pass appends nothing, so
  /// the next boot re-runs the gate from the same state.
  Future<void> _capResumedContext(Session session) async {
    if (_agent.state.messages.isEmpty) return;
    if (_runAbortRequested) return;
    final tokens = _liveRequestTokens();
    // gh-1680 AC4: the message-count trigger gates the boot cap too — a
    // resumed session riding at `cap − margin` compacts before its first
    // request instead of re-learning the refusal the hard way. PEEKING
    // gate (gh-1729 review): the armed E1 one-shot pass is consumed only
    // where a compaction actually runs — consuming it for a decision the
    // defer branch below does not act on would silently drop it.
    final overCap = _messageCapGatePending();
    if (!shouldCompact(
          tokens,
          _effectiveContextWindow,
          _effectiveCompactionSettings,
        ) &&
        !overCap) {
      return;
    }
    // Over the WINDOW itself: no request can ever be sent, and an LM
    // compaction pass here takes minutes on slow summarizers (the
    // goal_builder incident: a 3.5-minute boot cap read as a hung open
    // and was killed — every reopen re-paid it). Apply the mechanical
    // local-trim valve INSTANTLY instead: the boot completes in
    // milliseconds, the meter lands under the trigger, and the durable
    // LM compaction happens through the normal paths (the next prompt's
    // pre-flight or an explicit /compact). The session file keeps every
    // record — a restart replays and re-trims identically.
    if (tokens > _effectiveContextWindow) {
      final trimmed = localTrimValve(
        messages: _agent.state.messages,
        reason: 'the resumed transcript exceeded the context window',
        window: _effectiveContextWindow,
        settings: _effectiveCompactionSettings,
        overheadTokens: estimateRequestTokens(
          const [],
          systemPrompt: _agent.state.systemPrompt,
          tools: _agent.state.tools,
        ),
      );
      if (trimmed != null) {
        _agent.state.messages = trimmed.messages;
        _persistedCount = _agent.state.messages.length;
        final after = _liveRequestTokens();
        _logDiagnostic(
          'resume boot cap local-trim sid=$_logSid tokens=$tokens '
          '-> $after (dropped ${trimmed.dropped})',
        );
        io.writeln(
          _style.dim(
            '[resume] the restored context (~$tokens tokens) exceeded the '
            '$_effectiveContextWindow-token window — trimmed locally to '
            '~$after tokens; the full history stays in the session file '
            '(run /compact for an LLM summary)',
          ),
        );
        return;
      }
      // The valve found nothing droppable (a degenerate single-message
      // window): fall through to the LM pass below as the last resort.
    } else {
      // Over the TRIGGER but inside the window: the next request is
      // legal AS-IS — an LM summarization pass here costs minutes at a
      // moment the user is watching a session open (the yoclip open:
      // 194k tokens, a 3.5-minute boot cap the owner read as a hang).
      // Defer the durable compaction to the first turn's pre-flight
      // ([_maybeAutoCompact] runs before every prompt): the cap still
      // lands BEFORE any user work continues, just without blocking the
      // open. The meter idles at the honest pre-cap number (≤100%).
      _logDiagnostic(
        'resume boot cap deferred sid=$_logSid tokens=$tokens '
        '(inside the window — the first-turn pre-flight owns the '
        'durable compaction)',
      );
      // gh-1729 review: the deferred regime gets a visible receipt like
      // every other compaction decision on this path — a meter idling
      // just under the trigger with nothing happening reads as a stalled
      // boot without it.
      io.writeln(
        _style.dim(
          '[resume] context over the compaction trigger (~$tokens tokens, '
          'inside the window) — compaction deferred to the first message',
        ),
      );
      return;
    }
    _pushBusyPhase('Compacting context…');
    _logDiagnostic('resume boot cap start sid=$_logSid tokens=$tokens');
    try {
      await _runAutoCompact('[auto-compacted]', session: session);
    } on CancelledException {
      rethrow;
    } on Object catch (error) {
      _logDiagnostic('resume boot cap failed sid=$_logSid: $error');
      io.writeln(
        _style.dim(
          '[resume] boot compaction failed: $error — the session stayed '
          'over-window; compaction retries before the next turn',
        ),
      );
    } finally {
      _pushBusyPhase('');
    }
  }

  /// gh-1425 AC4 (the budget-guarded restore at checkpoint auto-close): a
  /// real user turn ends a checkpoint detour WITHOUT a rewind — the full
  /// detour history stays live, and the next `checkpoint` call auto-closes
  /// the stale mark mid-run. Whatever that restored context now carries
  /// must respect the same budget the boot cap gates on: when the live
  /// request sits over the compaction trigger (window − reserve), the
  /// remainder is compacted HERE — mid-run, inside the auto-closing tool
  /// call — and the loop adopts the capped transcript at the next turn
  /// boundary ([CheckpointRewindController.requestContextResync]), so no
  /// request ever rides the uncapped restore. Degradation (AC5) rides the
  /// same pipeline as everywhere else: summarizer failure → local-trim
  /// valve → `[context trimmed]`; an unexpected throw still boots/keeps
  /// the run alive with a visible dim note (the pre-flight re-fires before
  /// the next turn either way).
  Future<void> _guardCheckpointRestoreBudget(
    CheckpointAutoCloseReason reason,
    CheckpointState checkpoint,
  ) async {
    // Only the user-turn close restores an unpruned detour; an anchorGone
    // close means the transcript was ALREADY rebuilt (reload/compaction).
    if (reason != CheckpointAutoCloseReason.userTurn) return;
    if (_session == null) return;
    if (_agent.state.messages.isEmpty) return;
    if (_runAbortRequested) return;
    final tokens = _liveRequestTokens();
    if (!shouldCompact(
      tokens,
      _effectiveContextWindow,
      _effectiveCompactionSettings,
    )) {
      return;
    }
    _pushBusyPhase('Compacting context…');
    _logDiagnostic(
      'checkpoint restore budget guard start sid=$_logSid tokens=$tokens',
    );
    try {
      await _runAutoCompact('[auto-compacted]');
      // The compaction replaced state.messages MID-RUN: arm the resync so
      // the next turn boundary swaps the loop's stale context for the
      // capped one — the remainder rides no over-budget request.
      _checkpoints.requestContextResync();
      // Honest receipt: name the outcome, not the intent — a pass that
      // stayed over the trigger (huge keep region, degenerate overhead)
      // must not read as capped.
      final after = _liveRequestTokens();
      io.writeln(
        _style.dim(
          shouldCompact(
                after,
                _effectiveContextWindow,
                _effectiveCompactionSettings,
              )
              ? '[checkpoint] detour closed over the compaction trigger '
                    '($tokens tokens) — compaction ran but the context stayed '
                    'over the trigger ($after); it retries before the next turn'
              : '[checkpoint] detour closed over the compaction trigger '
                    '($tokens tokens) — context auto-compacted before the '
                    'next request',
        ),
      );
    } on CancelledException {
      rethrow;
    } on Object catch (error) {
      _logDiagnostic(
        'checkpoint restore budget guard failed sid=$_logSid: $error',
      );
      io.writeln(
        _style.dim(
          '[checkpoint] restore compaction failed: $error — compaction '
          'retries before the next turn',
        ),
      );
    } finally {
      _pushBusyPhase('');
    }
  }

  /// `/compact` manual override: same AutoCompactor pipeline as the
  /// auto-trigger, but unconditional — honours the user's explicit ask
  /// even when the threshold isn't crossed.
  Future<void> _runManualCompact() async {
    final session = _session;
    if (session == null) return;
    if (_agent.state.messages.isEmpty) {
      io.writeln('nothing to compact');
      return;
    }
    // An explicit /compact is a fresh user intent (issue #1085 round-1):
    // it overrides a stale abort marker from an earlier stopped run.
    _runAbortRequested = false;
    _pushBusyPhase('Compacting context…');
    final before = _liveRequestTokens();
    try {
      final reported = await _runAutoCompact('[compacted]');
      if (!reported && _liveRequestTokens() >= before) {
        // A no-op manual /compact (already compacted at the leaf) prints no
        // report block — say why instead of looking like a silent hang.
        // A run that DID report (or trimmed) never gets the note: its
        // receipt is already on screen, and a tiny transcript can free
        // nothing while still really compacting.
        io.writeln(
          _style.dim(
            'nothing to compact — every message is already summarized or '
            'the transcript is at its smallest',
          ),
        );
      }
    } on CancelledException {
      // Compaction-ONLY interrupt (issue #1085 round-2 review): Ctrl+C
      // during a bare /compact stops the compaction, not the session —
      // a dim receipt, no `error:` line, the REPL keeps working.
      io.writeln(_style.dim('compaction interrupted'));
    } finally {
      _pushBusyPhase('');
    }
  }

  /// Builds the per-host smol/main summarizers and runs the shared
  /// [AutoCompactor]. Used by both [_maybeAutoCompact] (gated by
  /// [shouldCompact]) and [_runManualCompact] (unconditional), plus the
  /// resume boot cap (which passes the session explicitly — at boot
  /// `_session` is not assigned yet). Returns whether a pass reported
  /// success (a rendered report block).
  Future<bool> _runAutoCompact(
    String label, {
    Session? session,
    bool force = false,
  }) async {
    // The user's explicit stop wins over any compaction (issue #1085
    // round-1): the abort must not merely cancel the IN-FLIGHT pass — it
    // must not be answered with a FRESH pass either (an aborted run's
    // post-fold, a relief retry after a cancelled relief). The engines
    // report cancelled summarizers as failed passes, so the funnel cannot
    // see this off the return value; the sticky flag can.
    _throwIfUserAborted();
    // Honest attempt accounting for the funnel's exhaustion verdict
    // (issue #1085 round-1): only passes that actually started count.
    _compactionPassesStarted++;
    // Backend agent mode (issue #155): bracket the run so the supervisor
    // sees why a turn stalled. Pre-flight runs carry the upcoming turn id
    // (the following agent_start reuses it). The end frame comes from the
    // pass result in [_AutoCompactorCliHooks.onPass] — the honest numbers.
    _hep?.compactionStart();
    // User-wired compaction cancellation (issue #1085 M3): a compaction
    // can run 15-30 min (pre-flight, mid-run relief, post-run) and the
    // run's own token does not exist for two of those windows — Ctrl+C
    // used to be a no-op for the whole duration. The token is also
    // LINKED to the live run token when one exists (mid-run relief), so
    // `_agent.abort()` cancels the in-flight summarizer too. Explicit
    // aborts only: the run idle watchdog is suspended around relief and
    // never cancels through here.
    final abort = CancelTokenSource();
    _activeCompactionAbort = abort;
    // gh-1430 E3: no agent events fire during compaction, so the
    // liveness watches would stay blind over a multi-minute summarizer
    // request — arm the tier-2 reasoning line for the window (line
    // mode/headless; the TUI busy row owns that surface).
    _waiting.compactionLivenessStart();
    final runToken = _agent.cancelToken;
    if (runToken != null) {
      unawaited(
        runToken.onCancel.then((_) => abort.cancel(runToken.cancelReason)),
      );
    }
    try {
      return await _runAutoCompactWithToken(
        label,
        abort.token,
        session: session,
        force: force,
      );
    } finally {
      _activeCompactionAbort = null;
      _waiting.compactionLivenessEnd();
      // Issue #1085 round-1 (review 🚨): a cancelled compaction must
      // surface as an ABORT, not as a failed pass. Both engines convert
      // the cancelled summarizer into `ok: false` (the classic `_attempt`
      // catch-all, and the structured judge's `on Object` fallback, which
      // then fires a SECOND provider call after the abort), so the
      // funnel's `on CancelledException` could never fire off the return
      // value alone and the loop relaunched compaction the user just
      // stopped.
      abort.token.throwIfCancelled();
    }
  }

