      mainSummary: mainSummarizer,
      smolModel: sources.smolModel,
      hooks: hooks,
      memoryExtractionHook: memoryExtractionHook,
      prompts: prompts,
      maxPasses: maxPasses,
      maxAttempts: maxAttempts,
      baseBackoff: baseBackoff,
      force: force,
      attemptBudget: attemptBudget,
